/* Proof-dependency graphs on the domain pages. Data: assets/deps-data.js (generated by scripts/depgraph.py).
   Layered layout: foundations at the top, every node below everything it depends on. */
(function () {
  var zh = (document.documentElement.lang || "").indexOf("zh") === 0;
  var T = zh
    ? { colon: "：", mutual: "互相依赖（图中只画指向账本中更早一方的边）", deps: "依赖", users: "被依赖", claims: "命题", thms: "Lean 定理", none: "无", hint: "点一个节点：上游（它用到的）与下游（用到它的）高亮。再点一次或点空白处恢复。", ext: "其他领域", hidden: function (n) { return n + " 个命题没有 Lean 定理（测试、T0–T2），不在图中。"; } }
    : { colon: ": ", mutual: "Mutual dependency (only the edge to the one earlier in the ledger is drawn)", deps: "Depends on", users: "Used by", claims: "Claims", thms: "Lean theorems", none: "none", hint: "Click a node: what it uses (upstream) and what uses it (downstream) are highlighted. Click again or on the background to reset.", ext: "other domain", hidden: function (n) { return n + " claims have no Lean theorem (tests, T0–T2) and are not drawn."; } };
  var NS = "http://www.w3.org/2000/svg";

  function el(tag, attrs, parent) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }
  function textWidth(s) {
    var w = 0;
    for (var i = 0; i < s.length; i++) w += s.charCodeAt(i) > 0x2e80 ? 13 : 7.2;
    return w;
  }
  function closure(start, adj) {
    var seen = {}, st = [start];
    while (st.length) {
      var v = st.pop();
      (adj[v] || []).forEach(function (w) { if (!seen[w]) { seen[w] = 1; st.push(w); } });
    }
    return seen;
  }

  function layout(nodes, edges) {
    var ids = nodes.map(function (n) { return n.id; }), idx = {};
    ids.forEach(function (id, i) { idx[id] = i; });
    var out = {}; // a depends on b
    ids.forEach(function (id) { out[id] = []; });
    // break cycles: keep an edge only if it does not close a cycle found by DFS order
    var state = {}, keep = [];
    function dfs(v) {
      state[v] = 1;
      edges.forEach(function (e) {
        if (e[0] !== v) return;
        if (state[e[1]] === 1) return;            // back edge: drop
        keep.push(e);
        if (!state[e[1]]) dfs(e[1]);
      });
      state[v] = 2;
    }
    ids.forEach(function (id) { if (!state[id]) dfs(id); });
    keep.forEach(function (e) { if (out[e[0]].indexOf(e[1]) < 0) out[e[0]].push(e[1]); });
    // layers: longest path from the foundations
    var layer = {};
    function lay(v) {
      if (layer[v] !== undefined) return layer[v];
      layer[v] = 0;
      var m = -1;
      out[v].forEach(function (w) { m = Math.max(m, lay(w)); });
      return (layer[v] = m + 1);
    }
    ids.forEach(lay);
    // transitive reduction for drawing
    var reach = {};
    ids.forEach(function (id) { reach[id] = closure(id, out); });
    var draw = [];
    ids.forEach(function (a) {
      out[a].forEach(function (b) {
        var implied = out[a].some(function (c) { return c !== b && reach[c][b]; });
        if (!implied) draw.push([a, b]);
      });
    });
    var nl = 0;
    ids.forEach(function (id) { nl = Math.max(nl, layer[id] + 1); });
    var rows = [];
    for (var i = 0; i < nl; i++) rows.push([]);
    ids.forEach(function (id) { rows[layer[id]].push(id); });
    var pos = {};
    function setPos() { rows.forEach(function (r) { r.forEach(function (id, j) { pos[id] = j / Math.max(1, r.length - 1); }); }); }
    setPos();
    var nb = {};
    ids.forEach(function (id) { nb[id] = []; });
    draw.forEach(function (e) { nb[e[0]].push(e[1]); nb[e[1]].push(e[0]); });
    for (var it = 0; it < 12; it++) {
      rows.forEach(function (r) {
        var bc = {};
        r.forEach(function (id) {
          var s = 0, c = 0;
          nb[id].forEach(function (w) { s += pos[w]; c++; });
          bc[id] = c ? s / c : pos[id];
        });
        r.sort(function (x, y) { return bc[x] - bc[y]; });
      });
      setPos();
    }
    return { rows: rows, layer: layer, draw: draw, out: out };
  }

  function render(box, d) {
    var nodes = d.nodes, byId = {};
    nodes.forEach(function (n) { byId[n.id] = n; });
    function label(n) { return d.level === "feature" ? (zh ? n.zh : n.en) : n.id; }
    var L = layout(nodes, d.edges);
    var H = 26, GX = 12, GY = 54, PAD = 10, W = {}, X = {}, Y = {}, width = 0;
    nodes.forEach(function (n) { W[n.id] = Math.ceil(textWidth(label(n))) + 20; });
    L.rows.forEach(function (r) {
      var w = r.reduce(function (s, id) { return s + W[id]; }, 0) + GX * (r.length - 1);
      width = Math.max(width, w);
    });
    L.rows.forEach(function (r, i) {
      var w = r.reduce(function (s, id) { return s + W[id]; }, 0) + GX * (r.length - 1);
      var x = PAD + (width - w) / 2;
      r.forEach(function (id) { X[id] = x; Y[id] = PAD + i * (H + GY); x += W[id] + GX; });
    });
    var svgW = width + 2 * PAD, svgH = PAD * 2 + L.rows.length * (H + GY) - GY;
    var wrap = document.createElement("div");
    wrap.className = "dg-wrap";
    var svg = el("svg", { viewBox: "0 0 " + svgW + " " + svgH, width: svgW, height: svgH, role: "img", "aria-label": zh ? "证明依赖图" : "Proof dependency graph" });
    wrap.appendChild(svg);
    var gE = el("g", { "class": "dg-edges" }, svg), gN = el("g", {}, svg);
    var edgeEls = L.draw.map(function (e) {
      var a = e[0], b = e[1];
      var x1 = X[b] + W[b] / 2, y1 = Y[b] + H, x2 = X[a] + W[a] / 2, y2 = Y[a], my = (y1 + y2) / 2;
      var p = el("path", { d: "M" + x1 + "," + y1 + " C" + x1 + "," + my + " " + x2 + "," + my + " " + x2 + "," + y2, "class": "dg-e" }, gE);
      return { a: a, b: b, el: p };
    });
    var nodeEls = {};
    nodes.forEach(function (n) {
      var g = el("g", { "class": "dg-n" + (n.ext ? " dg-ext" : "") + (n.tier ? " dg-" + n.tier : ""), tabindex: 0, role: "button" }, gN);
      el("rect", { x: X[n.id], y: Y[n.id], width: W[n.id], height: H, rx: 6 }, g);
      var t = el("text", { x: X[n.id] + W[n.id] / 2, y: Y[n.id] + H / 2 + 4, "text-anchor": "middle" }, g);
      t.textContent = label(n);
      var tt = el("title", {}, g);
      tt.textContent = label(n) + (n.tier ? " · " + n.tier : "") + (n.ext ? " · " + T.ext : "");
      nodeEls[n.id] = g;
      g.addEventListener("click", function (ev) { ev.stopPropagation(); select(n.id); });
      g.addEventListener("keydown", function (ev) { if (ev.key === "Enter" || ev.key === " ") { ev.preventDefault(); select(n.id); } });
    });
    var inn = {};
    nodes.forEach(function (n) { inn[n.id] = []; });
    Object.keys(L.out).forEach(function (a) { L.out[a].forEach(function (b) { inn[b].push(a); }); });
    var panel = document.createElement("div");
    panel.className = "dg-panel";
    var cur = null;
    function claimRow(id) {
      var desc = "";
      document.querySelectorAll("#claims td.l").forEach(function (td) { if (td.textContent.trim() === id) desc = td.nextElementSibling ? td.nextElementSibling.innerHTML : ""; });
      return desc;
    }
    function list(ids) {
      return ids.length ? ids.map(function (i) { var n = byId[i]; return "<code>" + (n ? label(n) : i) + "</code>"; }).join(" ") : T.none;
    }
    function select(id) {
      if (cur === id) id = null;
      cur = id;
      svg.classList.toggle("dg-focus", !!id);
      if (!id) { Object.keys(nodeEls).forEach(function (k) { nodeEls[k].setAttribute("class", nodeEls[k].getAttribute("class").replace(/ dg-(sel|up|down)/g, "")); }); edgeEls.forEach(function (e) { e.el.setAttribute("class", "dg-e"); }); panel.innerHTML = '<p class="dg-hint">' + T.hint + "</p>"; return; }
      var up = closure(id, L.out), down = closure(id, inn);
      Object.keys(nodeEls).forEach(function (k) {
        var c = nodeEls[k].getAttribute("class").replace(/ dg-(sel|up|down)/g, "");
        if (k === id) c += " dg-sel"; else if (up[k]) c += " dg-up"; else if (down[k]) c += " dg-down";
        nodeEls[k].setAttribute("class", c);
      });
      edgeEls.forEach(function (e) {
        var on = (e.a === id || up[e.a]) && (up[e.b]) ? " dg-up" : ((e.b === id || down[e.b]) && down[e.a] ? " dg-down" : "");
        e.el.setAttribute("class", "dg-e" + on);
      });
      var n = byId[id], h = "<p><b>" + label(n) + "</b>" + (n.tier ? ' <span class="tag ' + ({ T4: "s", T3: "m", T2: "p", T1: "f", T0: "n" }[n.tier] || "n") + '">' + n.tier + "</span>" : "") + "</p>";
      if (d.level === "claim") { var desc = claimRow(id); if (desc) h += "<p>" + desc + "</p>"; }
      h += "<p>" + T.deps + T.colon + list(L.out[id]) + "<br>" + T.users + T.colon + list(inn[id]);
      var mu = (d.mutual || []).filter(function (e) { return e[0] === id || e[1] === id; }).map(function (e) { return e[0] === id ? e[1] : e[0]; });
      if (mu.length) h += "<br>" + T.mutual + T.colon + list(mu);
      h += "</p>";
      if (d.level === "feature") {
        h += "<details><summary>" + T.claims + " (" + n.claims.length + ")</summary><ul>" + n.claims.map(function (c) {
          var cc = d.claims[c];
          return "<li><code>" + c + "</code> " + cc.tier + (cc.deps.length ? " ← " + cc.deps.map(function (x) { return "<code>" + x + "</code>"; }).join(" ") : "") + "</li>";
        }).join("") + "</ul></details>";
      } else if (n.thms && n.thms.length) {
        h += "<details><summary>" + T.thms + " (" + n.thms.length + ")</summary><ul>" + n.thms.map(function (t) { return "<li><code>" + t.replace(/^FormalInSilico\./, "") + "</code></li>"; }).join("") + "</ul></details>";
      }
      panel.innerHTML = h;
    }
    svg.addEventListener("click", function () { if (cur) select(cur); });
    box.appendChild(wrap);
    box.appendChild(panel);
    var note = document.createElement("p");
    note.className = "dg-note";
    note.textContent = d.hidden ? T.hidden(d.hidden) : "";
    box.appendChild(note);
    select(null);
  }

  function init() {
    if (!window.FIS_DEPS) return;
    document.querySelectorAll(".depgraph[data-domain]").forEach(function (box) {
      var d = window.FIS_DEPS[box.getAttribute("data-domain")];
      if (d) render(box, d);
    });
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})();
